def test_run_bash_code(docker_interpreter: DockerInterpreter):
    code = """
#!/bin/bash

fibonacci() {
    local n=$1
    if [[ $n -le 1 ]]; then
        echo $n
    else
        local a=$(fibonacci $((n - 1)))
        local b=$(fibonacci $((n - 2)))
        echo $((a + b))
    fi
}

fibonacci 10
"""
    result = docker_interpreter.run(code, "bash")
    assert "55" in result


